    void sendToPc(){if(busy)return;busy=true;feedback.setText(Loc.t("Preparing PC destination…"));JSONObject scopeRequest=options.payload(item.optInt("season"));worker.execute(()->{try{String id=item.optString("pcItemId",item.optString("id"));if(item.optString("id").startsWith("discover-")||item.optString("group").equals("show:"+item.optString("imdb"))){JSONObject payload=new JSONObject();DataStore.put(payload,"id",item.optString("imdb"));DataStore.put(payload,"type",item.optBoolean("movie")?"movie":"series");DataStore.put(payload,"season",item.optInt("season"));DataStore.put(payload,"episode",item.optInt("episode"));id=NoirApp.data.pcRequest("/v1/discover/save",payload).optString("id");}final String pcId=id;runOnUiThread(()->{busy=false;if(!isFinishing()){startActivity(new Intent(this,PcDownloadsActivity.class).putExtra("id",pcId).putExtra("season",!item.optBoolean("movie")).putExtra("scopeRequest",scopeRequest.toString()));finish();}});}catch(Exception e){runOnUiThread(()->{busy=false;reachable=false;pcDestination=false;feedback.setText(Loc.t("PC destination unavailable. Choose This phone to continue."));showForm();});}});}
