    void showForm(){revision++;page("Download…");if(scopeSheet!=null)scopeSheet.dismiss();NoirSheet s=new NoirSheet(this,"Download…",item.optString("title")+" · "+PhoneDownloadsManage.ltr(MainActivity.episode(item)));scopeSheet=s;s.dialog.setOnCancelListener(d->finish());s.root.setLayoutDirection(Loc.arabic?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);boolean movie=item.optBoolean("movie");
        List<NoirSheet.Tile> destinations=new ArrayList<>();destinations.add(new NoirSheet.Tile(pcDestination?"○":"✓","This phone",()->{pcDestination=false;showForm();},true));if(reachable)destinations.add(new NoirSheet.Tile(pcDestination?"✓":"○","My PC",()->{pcDestination=true;showForm();},true));s.tiles(2,destinations);
        String[] keys={movie?"This movie":"This episode","This season","Whole show","Next N episodes"};List<NoirSheet.Tile> cards=new ArrayList<>();for(String key:keys)cards.add(new NoirSheet.Tile(options.scope.equals(key)?"✓":"↓",key.equals("Next N episodes")?Loc.f("Next %d episodes",options.next):Loc.t(key),()->{options.scope=key;showForm();},!movie||key.equals("This movie")));s.tiles(2,cards);s.body.getChildAt(s.body.getChildCount()-2).setTag("scope-cards:0");s.body.getChildAt(s.body.getChildCount()-1).setTag("scope-cards:1");for(int n=0;n<4;n++){ViewGroup line=(ViewGroup)s.body.getChildAt(s.body.getChildCount()-2+n/2);View card=line.getChildAt(n%2);card.setTag("scope:"+keys[n]);if(options.scope.equals(keys[n]))card.setBackground(MainActivity.bg(0xff30291e,dp(14)));}
        if(options.scope.equals("Next N episodes")){s.note("Next episodes");LinearLayout step=column();step.setOrientation(LinearLayout.HORIZONTAL);step.setGravity(Gravity.CENTER_VERTICAL);Button minus=button("−",()->step(-1),false),plus=button("+",()->step(1),false);minus.setContentDescription(Loc.t("Fewer next episodes"));plus.setContentDescription(Loc.t("More next episodes"));minus.setEnabled(!movie&&options.next>1);plus.setEnabled(!movie&&options.next<25);step.addView(minus,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView count=text(Integer.toString(options.next),16);count.setTag("scope-next-count");count.setTextDirection(View.TEXT_DIRECTION_LTR);count.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);count.setGravity(Gravity.CENTER);step.addView(count,new LinearLayout.LayoutParams(dp(48),dp(48)));step.addView(plus,new LinearLayout.LayoutParams(dp(48),dp(48)));s.add(step);s.note("After your furthest watched episode");}View more=s.row("⌄",Loc.t("Quality and limits")+": "+summary(),null,true,null,this::moreOptions);more.setContentDescription(Loc.t("Quality and limits")+": "+summary());NoirIcons.rowIcon(more,"sliders");TextView moreLabel=(TextView)((ViewGroup)((ViewGroup)more).getChildAt(1)).getChildAt(0);moreLabel.setSingleLine(true);moreLabel.setEllipsize(android.text.TextUtils.TruncateAt.END);if(!movie)s.check("Keep this show ready",PhoneReadyJob.policy(NoirApp.data).keepReadyJson().has(item.optString("group")),(v,on)->{if(on)DownloadHubActivity.openKeepReady(this,item.optString("group"));else PhoneReadyJob.policy(NoirApp.data).keep(item.optString("group"),false);});if(!movie){TextView readyNote=s.note("Noir downloads the next episodes ahead, so they are ready when you are.");readyNote.setPadding(dp(4),0,dp(4),dp(8));}
        s.footerKeepOpen("Find releases",()->{NoirApp.data.pref("downloadScope:"+item.optString("group"),options.payload(item.optInt("season")).toString());scope=options.scope;numbers=options.input;if(pcDestination&&reachable){s.dismiss();sendToPc();return;}Set<String> saved=new HashSet<>(),queued=new HashSet<>();for(JSONObject e:NoirApp.data.episodes(item))if(!NoirApp.data.localFile(e.optString("id")).isEmpty())saved.add(e.optString("id"));for(JSONObject j:DataStore.objects(NoirApp.downloads.jobs()))if(!Arrays.asList("failed","cancelled").contains(j.optString("status")))queued.add(j.optString("id"));List<JSONObject> selected=movie?saved.contains(item.optString("id"))||queued.contains(item.optString("id"))?List.of():List.of(item):PhoneSeasonPlan.select(NoirApp.data.episodes(item),item.optInt("season"),item.optInt("episode"),options,saved,queued,System.currentTimeMillis());if(selected.isEmpty()){Toast.makeText(this,Loc.t("No released episodes match this scope."),Toast.LENGTH_SHORT).show();return;}s.dismiss();plan(selected);},true);s.show();Loc.apply(this);
    }
    void step(int delta){options.next=Math.max(1,Math.min(25,options.next+delta));options.scope="Next N episodes";showForm();}
    void optionSpinner(NoirSheet s,String label,String[] values,String selected,java.util.function.Consumer<String> changed){s.note(label);Spinner spinner=new Spinner(this);String[] labels=Arrays.stream(values).map(Loc::t).toArray(String[]::new);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setContentDescription(Loc.t(label));spinner.setSelection(Math.max(0,Arrays.asList(values).indexOf(selected)));s.add(spinner);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> v){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(v instanceof TextView)((TextView)v).setTextColor(MainActivity.WHITE);changed.accept(values[n]);}});}
    void moreOptions(){NoirSheet s=new NoirSheet(this,"More options",null);s.check("Skip watched",options.skipWatched,(v,on)->options.skipWatched=on);optionSpinner(s,"Quality",new String[]{"Any","720p","1080p","2160p"},options.quality,v->options.quality=v);optionSpinner(s,"Audio",new String[]{"All","English","Arabic","Japanese","Korean","Hindi","Spanish","French"},options.audio.equals("Any")?"All":options.audio,v->options.audio=v);sizeOptions(s,"Max per episode",new long[]{0,500L*1048576,1L<<30,2L<<30,4L<<30},options.maxEach,v->options.maxEach=v);sizeOptions(s,"Max total for this download",new long[]{0,5L<<30,10L<<30,20L<<30,50L<<30,100L<<30},options.maxTotal,v->options.maxTotal=v);s.check("Include specials",options.specials,(v,on)->options.specials=on);s.section("More ways to choose");optionSpinner(s,"Episodes",new String[]{item.optBoolean("movie")?"This movie":"This episode","This season","Whole show","Next N episodes","Missing episodes","Unwatched only","From episode N","Specific episodes","Several seasons / whole show"},options.scope,v->options.scope=v);s.note("Episode or season numbers (1,3-6)");EditText input=new EditText(this);input.setText(options.input);input.setTextColor(MainActivity.WHITE);input.setContentDescription(Loc.t("Episode or season numbers (1,3-6)"));input.setTextDirection(View.TEXT_DIRECTION_LTR);s.add(input);s.footer("Done",()->{options.input=input.getText().toString();showForm();},null,null);s.show();}
    void sizeOptions(NoirSheet s,String label,long[] values,long selected,java.util.function.LongConsumer changed){List<Long> ns=new ArrayList<>();for(long n:values)ns.add(n);if(!ns.contains(selected))ns.add(selected);String[] labels=ns.stream().map(n->n==0?"Off":PhoneDownloadsManage.size(n)).toArray(String[]::new);optionSpinner(s,label,labels,selected==0?"Off":PhoneDownloadsManage.size(selected),v->changed.accept(ns.get(Arrays.asList(labels).indexOf(v))));}
    void plan(List<JSONObject> episodes){if(busy)return;if((scope.equals("Specific episodes")||scope.equals("Several seasons")||scope.equals("From episode N")||scope.equals("Next N"))&&PhoneSeasonPlan.numbers(numbers).isEmpty()){feedback.setText("Enter episode or season numbers for this scope.");return;}if(episodes.isEmpty()){feedback.setText(Loc.t("No released episodes match this scope."));return;}busy=true;rows.clear();feedback.setText(Loc.t("Finding links on this phone…"));int view=revision;worker.execute(()->{try{config=new PhoneDownloadSettings(this).load();DataStore.put(config,"preferredResolution",options.quality);DataStore.put(config,"language",options.audio.equals("All")?"Any":options.audio);DataStore.put(config,"maxEpisodeBytes",options.maxEach);PhoneDownloadProvider provider=new PhoneDownloadProvider(config);Map<String,List<JSONObject>> packs=new HashMap<>();int completed=0;for(JSONObject episode:episodes){if(Thread.currentThread().isInterrupted())return;List<JSONObject> choices=new ArrayList<>();String warning="";try{List<JSONObject> found=provider.search(episode);for(JSONObject c:found)if(!c.optBoolean("pack"))choices.add(c);int checked=0;for(JSONObject pack:found)if(pack.optBoolean("pack")&&checked++<6){String key=pack.optString("service")+pack.optString("hash");if(!packs.containsKey(key)){try{packs.put(key,provider.files(pack,episode));}catch(Exception ignored){packs.put(key,List.of());}}}
                    for(List<JSONObject> files:packs.values())for(JSONObject f:files)if(episode.optBoolean("movie")||f.optInt("season")==episode.optInt("season")&&f.optInt("episode")==episode.optInt("episode"))choices.add(f);
                }catch(Exception e){warning="Search unavailable";}
                List<JSONObject> alternatives=PhoneDownloadProvider.ranked(choices,config,"");if(reachable&&episode.optBoolean("available")){JSONObject pc=new JSONObject();DataStore.put(pc,"service","pc-file");DataStore.put(pc,"name",Loc.t("Copy from your PC"));DataStore.put(pc,"size",episode.optLong("size"));if(options.maxEach==0||pc.optLong("size")>0&&pc.optLong("size")<=options.maxEach)alternatives.add(0,pc);}Row row=new Row(episode,alternatives);rows.add(row);int done=++completed;String note=warning;runOnUiThread(()->{if(view==revision)feedback.setText("Checked "+done+" / "+episodes.size()+" episodes"+(note.isEmpty()?"":" · "+note));});}
                runOnUiThread(()->{busy=false;if(!isFinishing()&&view==revision){applyCap();review();}});
            }catch(Exception e){runOnUiThread(()->{busy=false;if(view==revision)feedback.setText("Couldn't open phone settings or plan downloads. Check the manifest in Download settings.");});}});}
    void applyCap(){List<Row> available=new ArrayList<>();List<Long> sizes=new ArrayList<>();for(Row r:rows)if(r.choice!=null){available.add(r);sizes.add(r.choice.optLong("size"));}boolean[] over=PhoneSeasonPlan.cap(sizes,options.maxEach,options.maxTotal);for(int n=0;n<available.size();n++){available.get(n).over=over[n];if(over[n])available.get(n).selected=false;}}
    void review(){revision++;page("Review your download");destination();body.addView(text("One link per episode · tap a release to swap it. Cloud packs use your phone's saved debrid account.",14));total=text("",15);body.addView(total);
        for(Row row:rows){LinearLayout card=column();card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackground(MainActivity.bg(MainActivity.PANEL,dp(12)));CheckBox check=new CheckBox(this);check.setTextColor(MainActivity.WHITE);check.setText(MainActivity.episode(row.item)+" · "+row.item.optString("episodeTitle",row.item.optString("title")));check.setChecked(row.selected);check.setEnabled(row.choice!=null);check.setOnCheckedChangeListener((v,on)->{row.selected=on;totals();});card.addView(check);if(row.over)card.addView(text("Over your total limit",13));Button choice=button(label(row),()->{String[] labels=row.alternatives.stream().map(c->c.optString("name")+" · "+PcDownloadsActivity.size(c.optLong("size"))+" · "+c.optString("service")+(c.optString("fileName").isEmpty()?"":"\n"+c.optString("fileName"))).toArray(String[]::new);NoirSheet swap=new NoirSheet(this,"Episode alternatives",null);for(int n=0;n<labels.length;n++){final int index=n;swap.action("↓",labels[n],null,()->{row.choice=row.alternatives.get(index);row.selected=true;review();});}swap.show();},false);choice.setEnabled(row.choice!=null);card.addView(choice);body.addView(card);}
        totals();if(reachable)body.addView(button("Add PC / media-server alternatives",this::pcAlternatives,false));body.addView(button("Download",this::enqueue,true));body.addView(button("Change scope / refresh",()->{rows.clear();showForm();},false));feedback.setText(Loc.f("%d episodes without a matching link · adjust preferences or retry",rows.stream().filter(r->r.choice==null).count()));}
    void pcAlternatives(){if(busy)return;busy=true;feedback.setText("Checking PC / media-server alternatives…");int view=revision;worker.execute(()->{try{for(Row row:rows){JSONObject response=NoirApp.data.pcRequest("/v1/phone-downloads/search/"+row.item.optString("pcItemId",row.item.optString("id")),null);for(JSONObject c:DataStore.objects(response.optJSONArray("choices"))){DataStore.put(c,"movie",row.item.optBoolean("movie"));if(PhoneDownloadProvider.eligible(c,config))row.alternatives.add(c);}if(row.choice==null&&!row.alternatives.isEmpty()){row.choice=row.alternatives.get(0);row.selected=true;}}runOnUiThread(()->{busy=false;if(view==revision&&!isFinishing())review();});}catch(Exception e){runOnUiThread(()->{busy=false;if(view==revision)feedback.setText("PC alternatives unavailable. Phone links remain ready.");});}});}
    String label(Row row){return row.choice==null?Loc.t("No link matches phone preferences"):row.choice.optString("name")+" · "+PcDownloadsActivity.size(row.choice.optLong("size"))+" · "+row.choice.optString("service");}
    void choiceLabel(Row row,LinearLayout card){for(int n=0;n<card.getChildCount();n++)if(card.getChildAt(n) instanceof Button)((Button)card.getChildAt(n)).setText(label(row));}
    long free(){return new StatFs(NoirApp.downloads.defaultDirectory().getAbsolutePath()).getAvailableBytes();}
    void totals(){long bytes=0;int count=0,unknown=0;for(Row row:rows)if(row.selected&&row.choice!=null){count++;bytes+=row.choice.optLong("size");if(row.choice.optLong("size")<=0)unknown++;}total.setText(Loc.f("%d files · %s",count,PhoneDownloadsManage.ltr(PhoneDownloadsManage.size(bytes)))+(unknown>0?Loc.f(" + %d unknown sizes",unknown):"")+"\n"+Loc.f("%s free on phone · %s queued",PhoneDownloadsManage.ltr(PhoneDownloadsManage.size(free())),PhoneDownloadsManage.ltr(PhoneDownloadsManage.size(NoirApp.downloads.reservedBytes()))));}
    void enqueue(){long bytes=0;int count=0;for(Row row:rows)if(row.selected&&row.choice!=null){bytes+=row.choice.optLong("size");count++;}if(count==0){feedback.setText("Choose at least one available episode.");return;}long charged=0;for(Row row:rows)if(row.selected&&row.choice!=null)charged+=row.choice.optLong("size")>0?row.choice.optLong("size"):options.maxEach;if(options.maxTotal>0&&charged>options.maxTotal){feedback.setText(Loc.t("These choices exceed your total limit. Exclude episodes or change the limit and find releases again."));return;}if(bytes+NoirApp.downloads.reservedBytes()+32L*1024*1024>free()){feedback.setText(Loc.t("Not enough free phone storage."));return;}try{getSharedPreferences("phone-download-ui",0).edit().putString("destination","This phone").apply();for(Row row:rows)if(row.selected&&row.choice!=null){if(row.choice.optString("service").equals("pc-file")){JSONObject old=NoirApp.downloads.job(row.item.optString("id"));if(old!=null&&!old.optString("phoneSource").isEmpty())NoirApp.downloads.remove(row.item.optString("id"));NoirApp.downloads.enqueue(row.item);}else NoirApp.downloads.enqueuePhone(row.item,row.choice);}startForegroundService(new Intent(this,DownloadService.class));startActivity(new Intent(this,DownloadHubActivity.class).putExtra("tab","queue"));finish();}catch(Exception e){feedback.setText("Couldn't save the phone queue. Check free storage and try again.");}}
    @Override Button button(String value,Runnable action,boolean primary){Button b=super.button(Loc.t(value),action,primary);b.setContentDescription(Loc.t(value));return b;}
    @Override void page(String title){super.page(title);Loc.apply(this);}
    @Override public void onDestroy(){revision++;worker.shutdownNow();if(scopeSheet!=null)scopeSheet.dismiss();super.onDestroy();}
